def initials(name):
    parts = str(name).split()
    if not parts:
        return ""
    return "".join(p[0].upper() + "." for p in parts)

def wrap_text(text, width):
    words = str(text).split()
    if not words:
        return []
    lines, cur = [], ""
    for w in words:
        if not cur:
            cur = w
        elif len(cur) + 1 + len(w) <= width:
            cur += " " + w
        else:
            lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines

def csv_field(value):
    if any(ch in value for ch in [",", '"', "\n"]):
        return '"' + value.replace('"', '""') + '"'
    return value

def pluralise(word):
    w = str(word)
    if w.endswith(("s", "x", "z", "ch", "sh")):
        return w + "es"
    if len(w) > 1 and w.endswith("y") and w[-2].lower() not in "aeiou":
        return w[:-1] + "ies"
    return w + "s"

import unicodedata
def fold_accents(text):
    return "".join(ch for ch in unicodedata.normalize("NFD", text)
                   if unicodedata.category(ch) != "Mn")

SMALL = {"a", "an", "the", "of", "in", "on", "and", "or", "for", "to", "at", "by", "with"}
def title_case(text):
    words = str(text).split()
    out = []
    for i, w in enumerate(words):
        low = w.lower()
        if 0 < i < len(words) - 1 and low in SMALL:
            out.append(low)
        else:
            out.append(low[:1].upper() + low[1:])
    return " ".join(out)

def ellipsize(text, n):
    text = str(text)
    if len(text) <= n:
        return text
    return text[:n].rstrip() + "..."

def parse_kv(text):
    out = {}
    for part in str(text).split(";"):
        part = part.strip()
        if not part:
            continue
        if "=" not in part:
            raise ValueError(part)
        k, _, v = part.partition("=")
        out[k.strip()] = v.strip()
    return out

def caesar(text, k):
    out = []
    for ch in str(text):
        if "a" <= ch <= "z":
            out.append(chr((ord(ch) - 97 + k) % 26 + 97))
        elif "A" <= ch <= "Z":
            out.append(chr((ord(ch) - 65 + k) % 26 + 65))
        else:
            out.append(ch)
    return "".join(out)

def anagram_key(word):
    letters = [c for c in str(word).lower() if "a" <= c <= "z"]
    return "".join(sorted(letters))
